import{_ as l,o as i,c as t,a2 as r}from"./chunks/framework.DuPBmefI.js";const d=JSON.parse('{"title":"福建中学 · 2020–21年度 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"fukien","school_zh":"福建中学","school_en":"Fukien Secondary School","grade":"s1","year":"2020-21","year_label":"2020–21年度","type":"interview","title":"福建中学 · 2020–21年度 · 中一 · 面试","anonymous":true,"source_ids":["M011-2020-21"],"rounds":["r1","r2"]},"headers":[],"relativePath":"reports/fukien/s1/2020-21-interview.md","filePath":"reports/fukien/s1/2020-21-interview.md"}'),e={name:"reports/fukien/s1/2020-21-interview.md"};function n(s,o,p,a,u,g){return i(),t("div",null,[...o[0]||(o[0]=[r('<h1 id="福建中学-·-2020–21年度-·-中一-·-面试" tabindex="-1">福建中学 · 2020–21年度 · 中一 · 面试 <a class="header-anchor" href="#福建中学-·-2020–21年度-·-中一-·-面试" aria-label="Permalink to &quot;福建中学 · 2020–21年度 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/fukien">← 返回福建中学资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-m011-2020-21" tabindex="-1">资料来源：【其它机构】升中面试经验汇总_18-21.pdf <a class="header-anchor" href="#record-m011-2020-21" aria-label="Permalink to &quot;资料来源：【其它机构】升中面试经验汇总_18-21.pdf {#record-m011-2020-21}&quot;">​</a></h2><p><strong>资料类型：</strong> 面试反馈</p><p><strong>入学途径：</strong> 未注明</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong> 语言未注明</p><p><strong>多位学生反馈汇总</strong></p><p>以下按2020／21年度首輪的相近流程彙總，題目來自不同學生，不代表每位學生都遇到全部題目。</p><p>各段未逐一標明實際月份，以下為該年度視像面試的題目與流程彙整，不據此認定全部來自同一批次；不同形式另列。</p><p><strong>一般視像流程</strong></p><p>多份回憶記載中文及英文分開進行ZOOM面試，由中文及英文教師負責；有學生獨自參加。整體時間有約15分鐘的回憶，另有記錄寫每部分5分鐘，不能直接視為同一場次的統一計時。</p><p><strong>親子場次的差異</strong></p><p>同一首輪資料另有一份約10分鐘、全程粵語的親子面試回憶，由校長／行政主任會見學生及家長，要求家長陪同。此場次與前述學生獨自面試的安排不同。</p></blockquote><blockquote><p><strong>语文：</strong> 普通话及粤语（依题目与场次）</p><p><strong>朗讀與文章理解</strong></p><ul><li>多份回憶包括以普通話朗讀一段短文或一篇文章，再回答問題；有學生形容文章很短。</li><li>有場次閱讀理解包含1題普通話及2題粵語；另有場次先以普通話朗讀，再轉用粵語回答文章問題。</li><li>一組文章追問涉及閱讀帶來的世界：不能讀書的人有甚麼慘況？讀書人的另一個世界是怎樣的？請以一本書說明書中的幻想世界。</li><li>另有回憶僅記錄閱讀文章及問答，沒有提供具體題目。</li></ul><p><strong>興趣與時間安排</strong></p><ul><li>有場次在朗讀後問2題：為甚麼喜歡打乒乓球，以及喜歡甚麼類型的書，並要求舉例。</li><li>如何分配學習、乒乓球及足球的時間？足球與乒乓球之間較喜歡哪一項？</li></ul></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>英語學習與日常使用</strong></p><ul><li>喜歡怎樣學習英語？認為觀看電影是否有助學習英語？</li><li>是否喜歡英語，為甚麼？</li><li>是否使用社交媒體？平日是否經常觀看YouTube？</li></ul><p><strong>個人經歷與面試準備</strong></p><ul><li>為甚麼穿校服參加面試？此題出現在考生穿着校服的場次。</li><li>每天練球多久？每星期練習多少天？</li><li>如何準備面試？</li></ul><p>一份回憶將校服、每日練習、每周練習及面試準備記為4道問題；另有回憶將英語學習問題也列入題目清單，不將各份清單視為固定題數。</p><p><strong>生活與價值觀問題</strong></p><ul><li>“What do you like about living in Hong Kong?”</li><li>“What is your favourite local snack?”</li><li>“do you think the children in Hong Kong have enough sleep? How about you?”</li><li>“do you have a role model?”</li><li>是否有零用錢，是否足夠？</li><li>是否飼養寵物？</li></ul><p>另一份中文轉述亦提及榜樣（role model）問題，合併列於此處。</p></blockquote><blockquote><p><strong>综合面试：</strong> 粤语</p><p><strong>親子場次：學生問答</strong></p><p>以下來自前述10分鐘親子場次：</p><ul><li>如何看待網課？有網課是否便可取消實體課？</li><li>在家學習遇上困難時，有誰能協助？</li><li>乒乓球雙打時，若學校教練安排一位較弱的拍檔，會有甚麼感受、如何處理？</li></ul><p><strong>學生與家長分別回答的選校題</strong></p><p>教師先問學生，再問家長：還報考了哪些學校？若其他學校亦取錄，會選哪一間，為甚麼？</p></blockquote><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>综合面试：</strong> 中文及英语（依环节与场次）</p><p><strong>多位学生反馈汇总</strong></p><p>以下合併同年度第二輪中流程相近的學生及家長回憶，重複題目只列一次，特殊追問及語言差異保留在對應環節。</p><p><strong>自我介紹與延伸追問</strong></p><p>部分回憶記載自我介紹約1分鐘，可選任何語言；一位考生選用英語，後續全程亦以英語對答。考生提到喜歡數學書，考官便要求介紹所讀書籍；考生介紹奧數題解，理由是解題方法有趣。此經歷在匯編中重複出現，於此合併。</p><p>另有場次要求先以英語自我介紹，再轉用中文問答；其中一位學生被問如何平衡打球與學業，家長同場參與。</p><p><strong>個人特質與經歷</strong></p><ul><li>用甚麼植物形容自己？</li><li>若可選外國疫苗或中國疫苗，會如何選擇？</li><li>分享難忘的足球經歷。</li><li>分享小乒會故事比賽獲獎的經歷。</li><li>如何平衡打球與學業？</li></ul><p><strong>網上學習、生活安排及科技</strong></p><ul><li>如何看待網上課堂？視像學習對自己有甚麼影響？</li><li>較喜歡視像學習還是實體學習？如果視像學習途中出現問題，會怎樣處理？</li><li>下課後如何安排做功課、吃飯及觀看YouTube的時間？</li><li>喜歡在YouTube查找甚麼資料，對自己哪方面有幫助？</li><li>懂得哪些編程程式？</li><li>平日有沒有補習？如何看待補習？</li></ul><p><strong>體育情境與選校取捨</strong></p><ul><li>乒乓球比賽擔任後備時，抱持甚麼心態？</li><li>考試周若仍須到場擔任校隊後備，會如何應對？</li><li>有沒有其他心儀中學？會選哪一間，為甚麼？</li><li>住得較遠，為甚麼仍選擇觀塘的學校？</li></ul></blockquote><blockquote><p><strong>家长问答：</strong> 语言未注明</p><p><strong>照顧與親子相處</strong></p><ul><li>平日由誰照顧孩子、誰負責學業？</li><li>家長需要工作時，如何分配親子時間？</li><li>如何形容自己的子女？</li></ul><p><strong>選校原因與家庭共識</strong></p><ul><li>為甚麼選擇福建中學？不同回憶包括向父親及母親提問，以及追問母親是否認同這項選擇。</li><li>若自行分配學位申請的學校亦取錄，會如何在該校與福建中學之間選擇？</li></ul><p><strong>向學校提問</strong></p><p>最後讓家長提出想向學校了解的問題。</p></blockquote>',15)])])}const h=l(e,[["render",n]]);export{d as __pageData,h as default};
